-- ===== 自带校验(跑完一眼确认) =====
SELECT 'vocab' k, count(*) v, 44 expect FROM public.junior_vocab WHERE volume='required1' AND unit='U3'
UNION ALL SELECT 'grammar_points', count(*), 3 FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3'
UNION ALL SELECT 'grammar_questions', count(*), 60 FROM public.junior_grammar_questions WHERE point_id IN (SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3')
UNION ALL SELECT 'reading', count(*), 6 FROM public.junior_reading WHERE volume='required1' AND unit='U3'
UNION ALL SELECT 'cloze', count(*), 6 FROM public.junior_cloze WHERE volume='required1' AND unit='U3'
UNION ALL SELECT 'listening', count(*), 6 FROM public.junior_listening_exercises WHERE volume='required1' AND unit='U3'
UNION ALL SELECT 'writing', count(*), 1 FROM public.junior_writing_prompts WHERE volume='required1' AND unit='U3' ORDER BY k;
-- 分布校验:语法/阅读/完形/听力答案分布(应均匀)
SELECT 'grammar' rel, correct_answer ans, count(*) FROM public.junior_grammar_questions WHERE point_id IN (SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3') GROUP BY 2 ORDER BY 2;
