INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'fitness', 'n.', '/ˈfɪtnəs/', '健康;健壮;适合', 'Regular exercise is good for your fitness.', '经常锻炼有益于你的健康。', 'Sports and Fitness', 1, 0, 'senior', 'wordlist', 'required1', 'U3', 'health and fitness', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'soccer', 'n.', '/ˈsɒkə(r)/', '足球(运动)', 'We play soccer on the field every weekend.', '我们每个周末都在场上踢足球。', 'Sports and Fitness', 2, 0, 'senior', 'wordlist', 'required1', 'U3', 'play soccer', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'stadium', 'n.', '/ˈsteɪdiəm/', '体育场;运动场', 'Thousands of fans filled the stadium.', '成千上万的球迷挤满了体育场。', 'Sports and Fitness', 3, 0, 'senior', 'wordlist', 'required1', 'U3', 'a football stadium', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'boxing', 'n.', '/ˈbɒksɪŋ/', '拳击(运动)', 'He won the boxing match in the final round.', '他在最后一回合赢得了拳击比赛。', 'Sports and Fitness', 4, 0, 'senior', 'wordlist', 'required1', 'U3', 'a boxing match', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'badminton', 'n.', '/ˈbædmɪntən/', '羽毛球运动', 'Let''s play badminton after class.', '下课后我们打羽毛球吧。', 'Sports and Fitness', 5, 0, 'senior', 'wordlist', 'required1', 'U3', 'play badminton', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'marathon', 'n.', '/ˈmærəθən/', '马拉松赛跑', 'She trained for months to run a marathon.', '为了跑马拉松,她训练了好几个月。', 'Sports and Fitness', 6, 0, 'senior', 'wordlist', 'required1', 'U3', 'run a marathon', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'event', 'n.', '/ɪˈvent/', '比赛项目;大事;活动', 'The school holds a big sports event each spring.', '学校每年春天举办一场大型体育活动。', 'Sports and Fitness', 7, 0, 'senior', 'wordlist', 'required1', 'U3', 'a sports event', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'ski', 'v./n.', '/skiː/', '滑雪;滑雪的', 'We are going to ski in the mountains this winter.', '今年冬天我们打算去山里滑雪。', 'Sports and Fitness', 8, 0, 'senior', 'wordlist', 'required1', 'U3', 'go skiing', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'host', 'v./n.', '/həʊst/', '主办;主持;东道主', 'Our city will host the youth games next year.', '我们城市明年将主办青年运动会。', 'Sports and Fitness', 9, 0, 'senior', 'wordlist', 'required1', 'U3', 'host the Games', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'track', 'n.', '/træk/', '跑道;足迹;轨道', 'The runners lined up on the track.', '运动员们在跑道上排好了队。', 'Sports and Fitness', 10, 0, 'senior', 'wordlist', 'required1', 'U3', 'run on the track', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'gym', 'n.', '/dʒɪm/', '健身房;体育馆', 'I go to the gym three times a week.', '我每周去健身房三次。', 'Sports and Fitness', 11, 0, 'senior', 'wordlist', 'required1', 'U3', 'go to the gym', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'gymnastics', 'n.', '/dʒɪmˈnæstɪks/', '体操(训练)', 'She has done gymnastics since she was five.', '她从五岁起就练体操。', 'Sports and Fitness', 12, 0, 'senior', 'wordlist', 'required1', 'U3', 'do gymnastics', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'sweat', 'v./n.', '/swet/', '出汗;汗水', 'He was sweating after the long run.', '长跑之后他满身大汗。', 'Sports and Fitness', 13, 0, 'senior', 'wordlist', 'required1', 'U3', 'sweat a lot', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'legend', 'n.', '/ˈledʒənd/', '传奇人物;传说', 'The old coach is a living legend in our city.', '这位老教练是我们城市的传奇人物。', 'Sports and Fitness', 14, 0, 'senior', 'wordlist', 'required1', 'U3', 'a living legend', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'athlete', 'n.', '/ˈæθliːt/', '运动员', 'Every great athlete trains hard every day.', '每个伟大的运动员都每天刻苦训练。', 'Sports and Fitness', 15, 0, 'senior', 'wordlist', 'required1', 'U3', 'a great athlete', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'master', 'n./vt.', '/ˈmɑːstə(r)/', '高手;精通;掌握', 'It takes years to master a new sport.', '精通一项新运动需要数年时间。', 'Sports and Fitness', 16, 0, 'senior', 'wordlist', 'required1', 'U3', 'master a skill', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'honour', 'n.', '/ˈɒnə(r)/', '荣誉;尊敬;荣幸', 'Her win brought honour to the whole team.', '她的胜利为整个队伍带来了荣誉。', 'Sports and Fitness', 17, 0, 'senior', 'wordlist', 'required1', 'U3', 'bring honour to', '美式拼 honor;美音 /ˈɑːnər/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'glory', 'n.', '/ˈɡlɔːri/', '荣誉;光荣', 'The young player won glory for his country.', '这位年轻球员为祖国赢得了荣誉。', 'Sports and Fitness', 18, 0, 'senior', 'wordlist', 'required1', 'U3', 'win glory', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'medal', 'n.', '/ˈmedl/', '奖牌;勋章', 'She won a gold medal at the Olympics.', '她在奥运会上赢得了一枚金牌。', 'Sports and Fitness', 19, 0, 'senior', 'wordlist', 'required1', 'U3', 'win a gold medal', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'champion', 'n.', '/ˈtʃæmpiən/', '冠军;优胜者', 'Two weeks later, they became world champions.', '两周后,他们成了世界冠军。', 'Sports and Fitness', 20, 0, 'senior', 'wordlist', 'required1', 'U3', 'world champion', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'championship', 'n.', '/ˈtʃæmpiənʃɪp/', '锦标赛;冠军称号', 'Our team hopes to win the championship this year.', '我们队希望今年赢得锦标赛。', 'Sports and Fitness', 21, 0, 'senior', 'wordlist', 'required1', 'U3', 'win the championship', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'determination', 'n.', '/dɪˌtɜːmɪˈneɪʃn/', '决心;毅力', 'Her determination helped the team win.', '她的决心帮助球队取得了胜利。', 'Sports and Fitness', 22, 0, 'senior', 'wordlist', 'required1', 'U3', 'show determination', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'apart', 'adv.', '/əˈpɑːt/', '分离;分开', 'Without trust, a team will fall apart.', '没有信任,一支队伍会分崩离析。', 'Sports and Fitness', 23, 0, 'senior', 'wordlist', 'required1', 'U3', 'fall apart', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'injure', 'vt.', '/ˈɪndʒə(r)/', '使受伤;损害', 'He injured his knee during the match.', '他在比赛中伤了膝盖。', 'Sports and Fitness', 24, 0, 'senior', 'wordlist', 'required1', 'U3', 'injure one''s knee', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'injured', 'adj.', '/ˈɪndʒəd/', '受伤的', 'The injured player had to leave the field.', '受伤的球员不得不离场。', 'Sports and Fitness', 25, 0, 'senior', 'wordlist', 'required1', 'U3', 'an injured player', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'injury', 'n.', '/ˈɪndʒəri/', '伤害;损伤', 'A serious injury kept her out for months.', '一处严重的伤让她数月无法上场。', 'Sports and Fitness', 26, 0, 'senior', 'wordlist', 'required1', 'U3', 'a serious injury', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'captain', 'n.', '/ˈkæptɪn/', '队长;船长', 'As captain, she leads the team by example.', '作为队长,她以身作则带领球队。', 'Sports and Fitness', 27, 0, 'senior', 'wordlist', 'required1', 'U3', 'the team captain', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'graceful', 'adj.', '/ˈɡreɪsfl/', '优美的;优雅的', 'His graceful moves amazed the audience.', '他优雅的动作令观众惊叹。', 'Sports and Fitness', 28, 0, 'senior', 'wordlist', 'required1', 'U3', 'graceful moves', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'strength', 'n.', '/streŋθ/', '力量;体力', 'Mental strength made the champion unique.', '强大的心理素质让这位冠军与众不同。', 'Sports and Fitness', 29, 0, 'senior', 'wordlist', 'required1', 'U3', 'mental strength', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'failure', 'n.', '/ˈfeɪljə(r)/', '失败;失败的人(或事)', 'He learnt from every failure on the court.', '他从球场上的每次失败中学习。', 'Sports and Fitness', 30, 0, 'senior', 'wordlist', 'required1', 'U3', 'learn from failure', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'compete', 'vi.', '/kəmˈpiːt/', '竞争;比赛', 'Children who compete in a sport learn a lot.', '参加体育比赛的孩子收获很多。', 'Sports and Fitness', 31, 0, 'senior', 'wordlist', 'required1', 'U3', 'compete in a race', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'pretend', 'v.', '/prɪˈtend/', '假装;装扮', 'A player should not pretend to fall down.', '球员不该假装摔倒。', 'Sports and Fitness', 32, 0, 'senior', 'wordlist', 'required1', 'U3', 'pretend to fall', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'cheat', 'v./n.', '/tʃiːt/', '作弊;欺骗', 'Those who cheat in a game lose respect.', '比赛中作弊的人会失去尊重。', 'Sports and Fitness', 33, 0, 'senior', 'wordlist', 'required1', 'U3', 'cheat in a game', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'audience', 'n.', '/ˈɔːdiəns/', '观众;听众', 'In the end, the audience will see through it.', '最终,观众会看穿这一切。', 'Sports and Fitness', 34, 0, 'senior', 'wordlist', 'required1', 'U3', 'a large audience', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'positive', 'adj.', '/ˈpɒzətɪv/', '积极的;乐观的;肯定的', 'By being positive, she became healthier.', '保持积极心态,她变得更健康了。', 'Sports and Fitness', 35, 0, 'senior', 'wordlist', 'required1', 'U3', 'stay positive', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'slim', 'adj.', '/slɪm/', '苗条的;纤细的', 'I used to want to look like the slim girls on TV.', '我以前想要像电视上苗条的女孩那样。', 'Sports and Fitness', 36, 0, 'senior', 'wordlist', 'required1', 'U3', 'a slim figure', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'diet', 'n./vi.', '/ˈdaɪət/', '饮食;节食', 'A healthy diet matters as much as exercise.', '健康饮食和锻炼一样重要。', 'Sports and Fitness', 37, 0, 'senior', 'wordlist', 'required1', 'U3', 'a healthy diet', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'jog', 'vi./n.', '/dʒɒɡ/', '慢跑', 'I go for a jog in the park every morning.', '我每天早晨在公园慢跑。', 'Sports and Fitness', 38, 0, 'senior', 'wordlist', 'required1', 'U3', 'go for a jog', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'stress', 'n./vt.', '/stres/', '压力;强调', 'Sports help children deal with stress.', '运动帮助孩子应对压力。', 'Sports and Fitness', 39, 0, 'senior', 'wordlist', 'required1', 'U3', 'deal with stress', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'error', 'n.', '/ˈerə(r)/', '错误;差错', 'Everyone makes errors when learning a sport.', '学一项运动时人人都会犯错。', 'Sports and Fitness', 40, 0, 'senior', 'wordlist', 'required1', 'U3', 'make an error', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'powerful', 'adj.', '/ˈpaʊəfl/', '强有力的;有影响力的', 'The striker has a powerful kick.', '这名前锋有一脚强劲的射门。', 'Sports and Fitness', 41, 0, 'senior', 'wordlist', 'required1', 'U3', 'a powerful kick', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'rather', 'adv.', '/ˈrɑːðə(r)/', '相当;宁愿', 'Think about fitness rather than weight.', '多想健康,而不是体重。', 'Sports and Fitness', 42, 0, 'senior', 'wordlist', 'required1', 'U3', 'rather than', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'compare', 'vt.', '/kəmˈpeə(r)/', '比较;对比', 'I stopped comparing myself with models.', '我不再拿自己和模特比较。', 'Sports and Fitness', 43, 0, 'senior', 'wordlist', 'required1', 'U3', 'compare with', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'valuable', 'adj.', '/ˈvæljuəbl/', '宝贵的;有价值的', 'Sports play a valuable role in our lives.', '运动在我们生活中扮演着宝贵的角色。', 'Sports and Fitness', 44, 0, 'senior', 'wordlist', 'required1', 'U3', 'a valuable role', NULL);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('u3.01', '①基本构成(前肯后否 / 前否后肯)', 'A2', 10, '必修一 U3 — 陈述部分肯定→反问部分否定,陈述部分否定→反问部分肯定;反问部分用与陈述相应的 be/do/does/did + 主语代词(You play…, don''t you? / It isn''t…, is it?)。', 1, 'required1', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('u3.02', '②助动词·情态·完成时·特殊主语', 'A2', 10, '必修一 U3 — 陈述含 have/has done、can/will/should 等时,反问重复该助动词/情态动词;there be→…there;I am→aren''t I;everyone/nobody→they;含 never/few/nothing 等否定词的陈述视为否定→反问用肯定。', 2, 'required1', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('u3.03', '③祈使句·Let''s·答语逻辑', 'A2', 10, '必修一 U3 — 祈使句→will you;Let''s→shall we;Let me/us(请求)→will you;答语按事实:是肯定事实用 Yes,否定事实用 No,与问句形式无关。', 3, 'required1', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.01'), '"You play badminton every Friday, ____?"', 'don''t you', 'aren''t you', 'do you', 'didn''t you', 'A', '陈述肯定的一般现在时(play)→反问否定 don''t you。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.01'), '"She is a talented athlete, ____?"', 'doesn''t she', 'isn''t she', 'is she', 'wasn''t she', 'B', '陈述用 is(肯定)→反问否定 isn''t she。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.01'), '"They won the match yesterday, ____?"', 'don''t they', 'weren''t they', 'didn''t they', 'didn''t he', 'C', '陈述肯定的一般过去时(won)→反问否定 didn''t they。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.01'), '"It isn''t a real sport, ____?"', 'isn''t it', 'does it', 'was it', 'is it', 'D', '陈述否定(isn''t)→反问肯定 is it。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.01'), '"The coach trains the team hard, ____?"', 'doesn''t he', 'isn''t he', 'didn''t he', 'don''t he', 'A', '陈述肯定的一般现在时(trains,主语 he)→反问否定 doesn''t he。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.01'), '"You aren''t tired after the run, ____?"', 'aren''t you', 'are you', 'do you', 'were you', 'B', '陈述否定(aren''t)→反问肯定 are you。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.01'), '"We played really well today, ____?"', 'weren''t we', 'did we', 'didn''t we', 'don''t we', 'C', '陈述肯定的一般过去时(played)→反问否定 didn''t we。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.01'), '"Lang Ping is loved by fans at home and abroad, ____?"', 'doesn''t she', 'wasn''t she', 'is she', 'isn''t she', 'D', '陈述用 is(被动,肯定)→反问否定 isn''t she。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.01'), '"He doesn''t enjoy boxing, ____?"', 'does he', 'doesn''t he', 'is he', 'did he', 'A', '陈述否定(doesn''t)→反问肯定 does he。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.01'), '"The game starts at three o''clock, ____?"', 'don''t it', 'doesn''t it', 'isn''t it', 'didn''t it', 'B', '陈述肯定的一般现在时(starts,主语 it)→反问否定 doesn''t it。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.01'), '"Your team didn''t lose the final, ____?"', 'didn''t they', 'does it', 'did they', 'was it', 'C', '陈述否定的过去时(didn''t lose)→反问肯定 did they。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.01'), '"You''re coming to the gym with us, ____?"', 'are you', 'don''t you', 'weren''t you', 'aren''t you', 'D', '陈述用 ''re(be,肯定)→反问否定 aren''t you。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.01'), '"Long marathons are very tiring, ____?"', 'aren''t they', 'don''t they', 'isn''t it', 'weren''t they', 'A', '陈述用 are(肯定,主语 marathons→they)→反问否定 aren''t they。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.01'), '"Amy swims before breakfast every day, ____?"', 'don''t she', 'doesn''t she', 'isn''t she', 'didn''t she', 'B', '陈述肯定的一般现在时(swims,主语 she)→反问否定 doesn''t she。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.01'), '"It was an exciting final, ____?"', 'isn''t it', 'didn''t it', 'wasn''t it', 'weren''t it', 'C', '陈述用 was(肯定)→反问否定 wasn''t it。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.01'), '"The players aren''t ready yet, ____?"', 'aren''t they', 'do they', 'were they', 'are they', 'D', '陈述否定(aren''t)→反问肯定 are they。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.01'), '"We didn''t miss the bus to the stadium, ____?"', 'did we', 'didn''t we', 'do we', 'were we', 'A', '陈述否定的过去时(didn''t miss)→反问肯定 did we。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.01'), '"You like jogging in the park, ____?"', 'aren''t you', 'don''t you', 'do you', 'didn''t you', 'B', '陈述肯定的一般现在时(like)→反问否定 don''t you。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.01'), '"Michael Jordan played for the Chicago Bulls, ____?"', 'doesn''t he', 'wasn''t he', 'didn''t he', 'did he', 'C', '陈述肯定的过去时(played)→反问否定 didn''t he。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.01'), '"The tickets weren''t expensive, ____?"', 'weren''t they', 'are they', 'did they', 'were they', 'D', '陈述否定(weren''t)→反问肯定 were they。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.02'), '"You have watched the boxing match, ____?"', 'haven''t you', 'don''t you', 'have you', 'didn''t you', 'A', '陈述用现在完成时 have watched(肯定)→反问重复 haven''t you。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.02'), '"Lang Ping has won many championships, ____?"', 'doesn''t she', 'hasn''t she', 'has she', 'hadn''t she', 'B', '陈述用 has won(肯定)→反问重复 hasn''t she。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.02'), '"We can join the school team, ____?"', 'can we', 'don''t we', 'can''t we', 'couldn''t we', 'C', '陈述含情态 can(肯定)→反问 can''t we。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.02'), '"Zhangjiakou will host the youth ski race, ____?"', 'will it', 'doesn''t it', 'wouldn''t it', 'won''t it', 'D', '陈述含 will(肯定)→反问 won''t it。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.02'), '"You should warm up before training, ____?"', 'shouldn''t you', 'should you', 'don''t you', 'wouldn''t you', 'A', '陈述含情态 should(肯定)→反问 shouldn''t you。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.02'), '"There is a new gym near the school, ____?"', 'is there', 'isn''t there', 'isn''t it', 'doesn''t there', 'B', 'there be 句型,反问用 …there;肯定→否定 isn''t there。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.02'), '"There aren''t any tickets left, ____?"', 'aren''t there', 'are they', 'are there', 'is there', 'C', 'there be 否定→反问肯定 are there。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.02'), '"I am on the right team, ____?"', 'am I', 'amn''t I', 'aren''t you', 'aren''t I', 'D', 'I am 的反意疑问固定用 aren''t I。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.02'), '"Everyone enjoyed Sports Day, ____?"', 'didn''t they', 'didn''t he', 'weren''t they', 'didn''t everyone', 'A', 'everyone 作主语,反问用 they;肯定过去时→否定 didn''t they。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.02'), '"Nobody cheated in the race, ____?"', 'didn''t they', 'did they', 'did he', 'were they', 'B', 'nobody 含否定意义,陈述视为否定→反问肯定,用 they:did they。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.02'), '"This is your first time at this stadium, ____?"', 'isn''t this', 'doesn''t it', 'isn''t it', 'isn''t there', 'C', 'this 作主语,反问用 it;肯定→否定 isn''t it。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.02'), '"Jordan has never given up after a loss, ____?"', 'hasn''t he', 'does he', 'did he', 'has he', 'D', 'never 含否定,陈述视为否定→反问肯定 has he。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.02'), '"The runners could see the finish line, ____?"', 'couldn''t they', 'could they', 'didn''t they', 'can''t they', 'A', '陈述含情态 could(肯定)→反问 couldn''t they。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.02'), '"You won''t give up so easily, ____?"', 'won''t you', 'will you', 'do you', 'would you', 'B', '陈述含 won''t(否定)→反问肯定 will you。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.02'), '"We have set a good example for the team, ____?"', 'don''t we', 'have we', 'haven''t we', 'hadn''t we', 'C', '陈述用现在完成时 have set(肯定)→反问 haven''t we。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.02'), '"Few players knew the new rule, ____?"', 'didn''t they', 'did few', 'were they', 'did they', 'D', 'few 含否定意义,陈述视为否定→反问肯定 did they。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.02'), '"Nothing can stop a determined athlete, ____?"', 'can it', 'can''t it', 'can they', 'does it', 'A', 'nothing 含否定且作主语用 it,陈述视为否定→反问肯定 can it。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.02'), '"The captain has led the team to victory, ____?"', 'doesn''t she', 'hasn''t she', 'has she', 'didn''t she', 'B', '陈述用 has led(肯定)→反问 hasn''t she。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.02'), '"You''d practised for months before the final, ____?"', 'wouldn''t you', 'didn''t you', 'hadn''t you', 'hasn''t you', 'C', '''d = had(过去完成时 had practised,肯定)→反问 hadn''t you。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.02'), '"He must train very hard to win gold, ____?"', 'doesn''t he', 'needn''t he', 'must he', 'mustn''t he', 'D', '陈述含情态 must(表必要,肯定)→反问 mustn''t he。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.03'), '"Let''s go to the basketball game together, ____?"', 'shall we', 'will we', 'shall you', 'do we', 'A', 'Let''s(包括对方在内的提议)→反问固定用 shall we。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.03'), '"Pass me the ball, ____?"', 'shall you', 'will you', 'do you', 'won''t we', 'B', '祈使句→反问用 will you。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.03'), '"Let''s not waste any more time, ____?"', 'will we', 'shall you', 'shall we', 'do we', 'C', 'Let''s not… 仍是 Let''s 提议→反问用 shall we。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.03'), '"Be a good sport and shake hands, ____?"', 'shall we', 'are you', 'won''t we', 'will you', 'D', '祈使句(Be…)→反问用 will you。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.03'), '"Don''t pretend to fall down, ____?"', 'will you', 'do you', 'shall we', 'won''t you', 'A', '否定祈使句→反问仍用 will you。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.03'), '"Help me move the bench, ____?"', 'shall I', 'will you', 'shall we', 'do you', 'B', '祈使句(请对方帮忙)→反问用 will you。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.03'), '"Let''s invite Amy to the soccer match, ____?"', 'will we', 'shall you', 'shall we', 'won''t we', 'C', 'Let''s 提议→反问固定用 shall we。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.03'), '"Train a little harder every day, ____?"', 'do you', 'shall we', 'won''t we', 'will you', 'D', '祈使句(建议/命令对方)→反问用 will you。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.03'), '"Let''s warm up before we start, ____?"', 'shall we', 'will we', 'do we', 'shall you', 'A', 'Let''s 提议→反问固定用 shall we。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.03'), '"Turn off the lights in the gym, ____?"', 'shall we', 'will you', 'do you', 'won''t we', 'B', '祈使句→反问用 will you。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.03'), '"— It''s a beautiful day for soccer, isn''t it?" — "____, it is. Let''s play."', 'No', 'Sure', 'Yes', 'Never', 'C', '事实是肯定(天气好)→答语用 Yes,与后面 it is 一致。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.03'), '"— You don''t like running, do you?" — "____, I don''t. I prefer swimming."', 'Yes', 'Of course', 'Sure', 'No', 'D', '事实是否定(确实不喜欢跑步)→答语用 No,与后面 I don''t 一致。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.03'), '"— Our team won the final, didn''t they?" — "____, they did. We''re champions!"', 'Yes', 'No', 'Never', 'Not', 'A', '事实是肯定(赢了)→答语用 Yes,与后面 they did 一致。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.03'), '"— She isn''t injured, is she?" — "____, she isn''t. She''s fine."', 'Yes', 'No', 'Sure', 'Of course', 'B', '事实是否定(没受伤)→答语用 No,与后面 she isn''t 一致。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.03'), '"— You''ve finished the marathon, haven''t you?" — "____, I have. It was tough."', 'No', 'Never', 'Yes', 'Not', 'C', '事实是肯定(跑完了)→答语用 Yes,与后面 I have 一致。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.03'), '"— He can''t swim, can he?" — "____, he can. He learnt last year."', 'No', 'Never', 'Not', 'Yes', 'D', '事实是肯定(其实会游泳)→答语用 Yes,与后面 he can 一致。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.03'), '"— They didn''t cheat, did they?" — "____, they didn''t. They played fair."', 'No', 'Yes', 'Sure', 'Of course', 'A', '事实是否定(没作弊)→答语用 No,与后面 they didn''t 一致。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.03'), '"— It''s not going to rain, is it?" — "____, it isn''t. A good day for sports."', 'Yes', 'No', 'Sure', 'Of course', 'B', '事实是否定(不会下雨)→答语用 No,与后面 it isn''t 一致。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.03'), '"— You''ll come to the gym, won''t you?" — "____, I will. See you at six."', 'No', 'Never', 'Yes', 'Not', 'C', '事实是肯定(会来)→答语用 Yes,与后面 I will 一致。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U3' AND code='u3.03'), '"— There''s a game this Saturday, isn''t there?" — "____, there is. Against No. 2 High."', 'No', 'Never', 'Not', 'Yes', 'D', '事实是肯定(有比赛)→答语用 Yes,与后面 there is 一致。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'A Living Legend: Lang Ping', 'As a player, Lang Ping brought honour and glory to her country. As a coach, she led the China women''s volleyball team to medals at world championships and the Olympics. When the team was preparing for the 2015 World Cup, her determination was tested. The team she had built was falling apart. One of the best players had been injured, and the captain had to leave because of heart problems. Losing two key players was a huge challenge, but Lang Ping did not lose heart. She had faced hard times before, and she believed her young players could win if they worked together as a team. Two weeks later, they were world champions. Then in 2016, she led her team to Olympic gold in Brazil. To fans at home and abroad, she is loved not only for her medals but for her spirit.', '记叙·排球传奇郎平', 143, '[{"q":"What happened to the team while preparing for the 2015 World Cup?","answer":"A","options":["It lost two important players and nearly broke apart.","It won every game easily.","It refused to train at all.","It changed its coach."],"explanation":"原文 ''the team was falling apart… lost two key players'' 的转述;其余与原文不符。"},{"q":"How did Lang Ping react to the difficulties?","answer":"B","options":["She gave up coaching.","She stayed confident in her young players.","She blamed the injured player.","She left for another country."],"explanation":"原文 ''did not lose heart… believed her young players could win'' 的转述。"},{"q":"Why do fans love Lang Ping, according to the text?","answer":"A","options":["For both her medals and her spirit.","Only because she is rich.","Only because she is famous on TV.","Because she never lost a single match."],"explanation":"末句 ''loved not only for her medals but for her spirit'' 的转述;D 与事实不符。"}]'::jsonb, '[{"word":"honour","cn":"荣誉"},{"word":"determination","cn":"决心"},{"word":"champion","cn":"冠军"}]'::jsonb, 2, 'required1', 'U3');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'What Made Air Jordan Unique', 'When Michael Jordan''s feet left the ground, time seemed to stand still. Known as "Air Jordan", he changed basketball with his graceful moves and jumps. His skills were impressive, but it was his mental strength that made him truly unique. In the final seconds of a close game, Jordan always seemed to find a way to win. He once said that the secret to his success was learning from his failures. "I can accept failure; everyone fails at something. But I can''t accept not trying." Losing games taught him to practise harder and never give up. Off the court, Jordan has learnt to share his success with others. The Boys and Girls Club he started in Chicago has been helping young people since 1996. For him, true greatness is measured not only by points scored but by the way a person keeps trying and helps others.', '记叙·乔丹的心理素质', 146, '[{"q":"What does the writer say made Jordan special?","answer":"B","options":["His height alone.","His strong mind under pressure.","His expensive shoes.","His loud voice."],"explanation":"原文 ''it was his mental strength that made him truly unique'' 的转述。"},{"q":"What lesson did losing games teach Jordan?","answer":"C","options":["To stop playing basketball.","To blame his teammates.","To train harder and keep going.","To avoid hard opponents."],"explanation":"原文 ''taught him to practise harder and never give up'' 的转述。"},{"q":"What has Jordan done off the court since 1996?","answer":"D","options":["Refused to meet his fans.","Stopped sharing his success.","Opened a shoe factory abroad.","Helped young people through a club he started."],"explanation":"原文 ''Boys and Girls Club he started… helping young people since 1996'' 的转述。"}]'::jsonb, '[{"word":"graceful","cn":"优雅的"},{"word":"strength","cn":"力量;心理素质"},{"word":"failure","cn":"失败"}]'::jsonb, 2, 'required1', 'U3');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Going Positive', 'I always wanted to look like the slim girls on TV, even though I knew it was impossible. I worried about my weight and tried every new diet I read about online. Then I read an article that said instead of asking "Am I fat?" I should ask "Am I fit?" I had no idea a single letter could make such a difference. Once I started thinking about fitness rather than weight, things began to change. Instead of saying "I want to lose three kilos", I would say "I want to run two kilometres in eight minutes" or "I want to do thirty push-ups". Rather than cutting out the foods I enjoyed, I added healthy foods to my meals. I could still have a burger now and then, but I would add a salad or an apple. Finally, I stopped comparing myself with models and made a list of things I liked about myself. By being positive, I became both happier and healthier.', '记叙·从减肥到健身', 163, '[{"q":"What change in thinking helped the writer most?","answer":"A","options":["Asking about fitness instead of weight.","Following stricter diets.","Watching more TV shows.","Eating only bananas."],"explanation":"原文 ''instead of asking Am I fat? … Am I fit?'' 是转折关键的转述。"},{"q":"How did the writer change her eating habits?","answer":"B","options":["She stopped eating completely.","She added healthy foods instead of giving up the ones she liked.","She ate only burgers.","She never ate fruit."],"explanation":"原文 ''Rather than cutting out the foods I enjoyed, I added healthy foods'' 的转述。"},{"q":"What was the final result of her new attitude?","answer":"C","options":["She felt worse about herself.","She gave up sports.","She became happier and healthier.","She lost all her friends."],"explanation":"末句 ''became both happier and healthier'' 的转述。"}]'::jsonb, '[{"word":"slim","cn":"苗条的"},{"word":"diet","cn":"饮食"},{"word":"positive","cn":"积极的"}]'::jsonb, 2, 'required1', 'U3');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Why Sports Matter for Children', 'Sports play a very valuable role in children''s lives. Children who compete in a sport learn how to deal with failure, because even though they work hard to master the skills they need, it does not mean they will always win. Learning to lose with a smile is a skill that helps them far beyond the playing field. Sports also help children see that cheating is foolish. There is no use pretending to fall down or be hurt, because in the end the audience will see through it. Honest effort earns more respect than an easy win. Taking part in sports is fun but not always easy, so it helps children learn how to handle stress, something everyone must face in life. Through wins and losses, young players slowly build the determination and team spirit that will serve them as adults.', '议论·运动为何重要', 141, '[{"q":"Why does competing in sport help children deal with failure?","answer":"D","options":["Because they never lose a game.","Because coaches let them win.","Because failure is never mentioned.","Because hard work does not always lead to winning."],"explanation":"原文 ''work hard… does not mean they will always win'' 的转述。"},{"q":"What does the writer say about cheating?","answer":"A","options":["It is foolish because people will notice.","It is a clever way to win.","It is necessary in team sports.","It helps build respect."],"explanation":"原文 ''cheating is foolish… the audience will see through it'' 的转述。"},{"q":"Besides failure and honesty, what else do sports teach children?","answer":"B","options":["How to avoid all hard work.","How to handle stress in life.","How to win without effort.","How to give up early."],"explanation":"原文 ''learn how to handle stress'' 的转述。"}]'::jsonb, '[{"word":"compete","cn":"竞争;参赛"},{"word":"cheat","cn":"作弊"},{"word":"stress","cn":"压力"}]'::jsonb, 2, 'required1', 'U3');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'A School Sports Survey', 'Our group of five students did a survey of our classmates to find out what sports interests and needs they have. We hoped the results would help the school decide which new sports clubs to set up. The first question we asked was "What is your favourite sport?" Eight out of fifteen students said that one-on-one sports, such as table tennis or badminton, were their favourite way to get exercise. Five out of fifteen preferred team sports, such as football. Only two said they liked to exercise alone, such as jogging or walking. We also found that most students prefer to do sports in the late afternoon, after classes are over. Based on these answers, we suggest that the school start a table tennis club and a football club first. We believe well-organised clubs would encourage more students to exercise regularly and stay healthy.', '说明·校园运动调查', 144, '[{"q":"Why did the students carry out the survey?","answer":"C","options":["To decide who is the best athlete.","To cancel all sports classes.","To help the school choose new sports clubs.","To compare two schools."],"explanation":"原文 ''help the school decide which new sports clubs to set up'' 的转述。"},{"q":"Which type of sport was most popular among the students?","answer":"D","options":["Team sports like football.","Exercising alone like jogging.","Swimming.","One-on-one sports like table tennis."],"explanation":"原文 ''Eight out of fifteen… one-on-one sports'' 最多。"},{"q":"What did the group suggest to the school?","answer":"A","options":["Setting up clubs for table tennis and football.","Closing the gym.","Buying new uniforms.","Stopping the afternoon classes."],"explanation":"原文 ''suggest that the school start a table tennis club and a football club'' 的转述。"}]'::jsonb, '[{"word":"survey","cn":"调查"},{"word":"event","cn":"比赛项目;活动"},{"word":"jog","cn":"慢跑"}]'::jsonb, 2, 'required1', 'U3');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'What Good Sportsmanship Means', 'Three students were talking about sportsmanship. Cao Jing believed an athlete should do his or her best to win, because fans and the country are watching. Lily disagreed, saying that good sportsmanship is more important than winning; if another player falls, you should stop and help. Max added that an athlete should never pretend to fall down, even if it helps the team, because cheating is wrong. They did not fully agree, but all of them felt that playing fair matters. A true champion, they decided, is not only the one who scores the most points but also the one who respects the rules and the other players. In the end, the audience remembers good behaviour long after the final score is forgotten. Winning feels good for a day, but a name for fair play lasts for years.', '议论·体育精神', 138, '[{"q":"What did Lily think was most important?","answer":"B","options":["Winning at any cost.","Good sportsmanship over winning.","Scoring the most points.","Pretending to be hurt."],"explanation":"原文 ''good sportsmanship is more important than winning'' 的转述。"},{"q":"Why did Max say a player should not pretend to fall?","answer":"C","options":["Because it is too tiring.","Because the coach forbids it.","Because dishonest play is wrong, even when it benefits his side.","Because nobody is watching."],"explanation":"原文 ''never pretend to fall… cheating is wrong'' 的转述。"},{"q":"According to the passage, what makes a true champion?","answer":"D","options":["Always winning the trophy.","Having the most fans.","Never losing a single point.","Respecting the rules and other players, not just scoring."],"explanation":"原文 ''not only the one who scores the most… respects the rules and the other players'' 的转述。"}]'::jsonb, '[{"word":"sportsmanship","cn":"体育精神"},{"word":"pretend","cn":"假装"},{"word":"audience","cn":"观众"}]'::jsonb, 2, 'required1', 'U3');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required1', 'U3', 'Joining the Gym', 'Last month I decided to get (1)____, so I joined a gym near my home. On my first day I felt nervous, but a friendly coach showed me around. He told me to (2)____ up before every workout so that I would not hurt myself. At first even ten push-ups made me (3)____ a lot. I wanted to give (4)____ many times, but I remembered my goal and kept going. Slowly, my (5)____ grew and the exercises felt easier. The coach said the secret was to train a little every day (6)____ than too much at once. Now I go to the gym three times a (7)____. I have more energy, sleep better, and feel (8)____ about myself. Exercise has become a part of my life that I really (9)____. If you want to be healthier, why not (10)____ a gym, too?', 142, 2, '[{"q":"1","answer":"A","options":["fit","rich","late","lost"],"explanation":"get fit 变得健康。"},{"q":"2","answer":"B","options":["give","warm","wake","look"],"explanation":"warm up 热身。"},{"q":"3","answer":"C","options":["sleep","smile","sweat","speak"],"explanation":"运动让人 sweat 出汗。"},{"q":"4","answer":"D","options":["in","off","out","up"],"explanation":"give up 放弃。"},{"q":"5","answer":"A","options":["strength","weight","stress","error"],"explanation":"体力 strength 增长。"},{"q":"6","answer":"B","options":["more","rather","less","other"],"explanation":"rather than 而不是。"},{"q":"7","answer":"C","options":["day","year","week","month"],"explanation":"three times a week 每周三次。"},{"q":"8","answer":"D","options":["afraid","sorry","tired","positive"],"explanation":"feel positive 感觉积极。"},{"q":"9","answer":"A","options":["enjoy","hate","miss","fear"],"explanation":"really enjoy 真正享受。"},{"q":"10","answer":"B","options":["leave","join","close","lose"],"explanation":"join a gym 加入健身房。"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required1', 'U3', 'My First Marathon', 'I had never run a (1)____ before, so I trained for six months. On race day, thousands of runners filled the (2)____ start line, and a huge (3)____ cheered for us. The first ten kilometres felt easy, but later my legs began to (4)____. I really wanted to stop, yet I did not lose (5)____. I kept telling myself, "You can make (6)____!" When I finally crossed the finish line, I was covered in (7)____ but full of joy. I did not win a (8)____, and I was not the fastest, but finishing was a kind of (9)____ for me. That day taught me that with enough (10)____, an ordinary person can do something amazing.', 115, 2, '[{"q":"1","answer":"C","options":["medal","machine","marathon","meeting"],"explanation":"run a marathon 跑马拉松。"},{"q":"2","answer":"D","options":["empty","narrow","quiet","crowded"],"explanation":"crowded start line 拥挤的起跑线。"},{"q":"3","answer":"A","options":["audience","machine","garden","library"],"explanation":"audience 观众欢呼。"},{"q":"4","answer":"B","options":["grow","hurt","jump","rest"],"explanation":"legs began to hurt 腿开始疼。"},{"q":"5","answer":"C","options":["weight","money","heart","time"],"explanation":"lose heart 泄气。"},{"q":"6","answer":"D","options":["out","up","off","it"],"explanation":"make it 成功/坚持到。"},{"q":"7","answer":"A","options":["sweat","snow","dust","paint"],"explanation":"covered in sweat 满身大汗。"},{"q":"8","answer":"B","options":["ticket","medal","letter","ball"],"explanation":"win a medal 赢奖牌。"},{"q":"9","answer":"C","options":["failure","danger","victory","problem"],"explanation":"完赛对我是一种 victory 胜利。"},{"q":"10","answer":"D","options":["money","luck","fear","determination"],"explanation":"with enough determination 凭足够的决心。"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required1', 'U3', 'The Young Swimmer', 'Mei started swimming when she was only six years old. Every morning she got up before sunrise to (1)____. The water was cold and her arms felt heavy, but she never (2)____ a single practice. Her coach often said she had the (3)____ to become a great athlete one day. When she lost a race, she did not feel like a (4)____. Instead, she studied her mistakes and tried to (5)____ the skills she still lacked. "Everyone (6)____ at something," her coach reminded her, "but a true champion learns from it." Year after year, Mei''s hard work began to (7)____ a difference. Last summer she finally won a gold (8)____ at the city games. Standing on the stage, she felt proud, not because she had beaten others, but because she had never (9)____ up on her (10)____.', 137, 2, '[{"q":"1","answer":"A","options":["train","sleep","eat","read"],"explanation":"起床去 train 训练。"},{"q":"2","answer":"B","options":["won","missed","started","loved"],"explanation":"never missed a practice 从不缺席训练。"},{"q":"3","answer":"C","options":["money","ticket","strength","noise"],"explanation":"have the strength 有实力/力量。"},{"q":"4","answer":"D","options":["champion","captain","master","failure"],"explanation":"输了不觉得自己是 failure 失败者。"},{"q":"5","answer":"A","options":["master","lose","waste","forget"],"explanation":"master the skills 掌握技能。"},{"q":"6","answer":"B","options":["wins","fails","sleeps","cheats"],"explanation":"everyone fails 人人都会失败。"},{"q":"7","answer":"C","options":["lose","take","make","find"],"explanation":"make a difference 产生影响。"},{"q":"8","answer":"D","options":["path","view","diet","medal"],"explanation":"gold medal 金牌。"},{"q":"9","answer":"A","options":["given","got","looked","kept"],"explanation":"given up 放弃(never given up)。"},{"q":"10","answer":"B","options":["error","dream","stress","fear"],"explanation":"never given up on her dream 没放弃梦想。"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required1', 'U3', 'Fair Play', 'During the school football match, our team was losing by one goal. With only two minutes left, a player from the other team fell down near our goal. Some of my teammates shouted that he was only (1)____ to be hurt so that he could win a free kick. But our captain ran over to (2)____ him stand up. "Even if it helps us, we should never (3)____," he said. The (4)____ on the stands grew quiet, and then they began to clap. In the end, we did not (5)____ the match, but everyone respected our team. Our coach told us that good (6)____ is more important than winning. "A medal shines for a while," he said, "but a good (7)____ lasts for years." That day I learnt that playing (8)____ matters more than the final (9)____. I felt proud to be part of such a (10)____.', 147, 2, '[{"q":"1","answer":"C","options":["training","jumping","pretending","resting"],"explanation":"pretending to be hurt 假装受伤。"},{"q":"2","answer":"D","options":["stop","watch","leave","help"],"explanation":"help him stand up 帮他站起来。"},{"q":"3","answer":"A","options":["cheat","train","smile","agree"],"explanation":"never cheat 决不作弊。"},{"q":"4","answer":"B","options":["players","audience","coaches","workers"],"explanation":"看台上的 audience 观众。"},{"q":"5","answer":"C","options":["lose","start","win","watch"],"explanation":"did not win the match 没赢比赛。"},{"q":"6","answer":"D","options":["weather","homework","music","sportsmanship"],"explanation":"good sportsmanship 良好的体育精神。"},{"q":"7","answer":"A","options":["name","ball","seat","gym"],"explanation":"a good name 好名声。"},{"q":"8","answer":"B","options":["fast","fair","late","alone"],"explanation":"playing fair 公平比赛。"},{"q":"9","answer":"C","options":["ticket","path","score","view"],"explanation":"the final score 最终比分。"},{"q":"10","answer":"D","options":["shop","city","class","team"],"explanation":"part of such a team 这样一支队伍的一员。"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required1', 'U3', 'From the Sofa to the Track', 'A year ago, I spent every evening sitting on the sofa, and I felt tired all the time. One day a friend asked me to go for a (1)____ with her in the park. I could hardly run for five minutes without stopping, but she told me not to (2)____ myself with others and just to enjoy the fresh air. Little by little, running became (3)____ for me. Instead of asking "Am I thin?", I started asking "Am I (4)____?" That small change made a big (5)____. Rather than (6)____ out the foods I loved, I simply added more fruit and vegetables to my (7)____. I also learnt to deal with (8)____ by jogging after a hard day at school. Now I feel both happier and (9)____. Exercise did not just change my body; it changed the way I (10)____ about myself.', 142, 2, '[{"q":"1","answer":"A","options":["jog","sleep","drive","meal"],"explanation":"go for a jog 去慢跑。"},{"q":"2","answer":"B","options":["enjoy","compare","help","teach"],"explanation":"compare myself with others 与别人比较。"},{"q":"3","answer":"C","options":["boring","harder","easier","slower"],"explanation":"became easier 变得更轻松。"},{"q":"4","answer":"D","options":["rich","tall","busy","fit"],"explanation":"Am I fit? 我健康吗(对应课文观念)。"},{"q":"5","answer":"A","options":["difference","mistake","noise","problem"],"explanation":"made a big difference 带来很大变化。"},{"q":"6","answer":"B","options":["finding","cutting","looking","calling"],"explanation":"cutting out the foods 把食物戒掉。"},{"q":"7","answer":"C","options":["weight","track","diet","gym"],"explanation":"added to my diet 加进饮食。"},{"q":"8","answer":"D","options":["honour","glory","medal","stress"],"explanation":"deal with stress 应对压力。"},{"q":"9","answer":"A","options":["healthier","sadder","weaker","lazier"],"explanation":"happier and healthier 更快乐更健康。"},{"q":"10","answer":"B","options":["forget","think","worry","doubt"],"explanation":"the way I think about myself 看待自己的方式。"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required1', 'U3', 'A Word from the Coach', 'Before the championship final, our coach gathered the whole team in the changing room. "Tomorrow will be hard," he said, "but I believe in every one of you." He reminded us that a team can only win if its members (1)____ together, not as separate players. "When one of you is (2)____ and has to leave the field, the rest must not lose (3)____," he went on. He had faced difficult (4)____ before, and he knew how it felt. "Skills are important," he said, "but mental (5)____ wins the close games." He told us to learn from every (6)____ instead of being afraid of it. "Do your (7)____, play (8)____, and respect your opponents." His calm words gave us (9)____. The next day, we stepped onto the field as one team, ready to (10)____ for the title.', 137, 2, '[{"q":"1","answer":"C","options":["fall","stay","work","stop"],"explanation":"work together 团结协作。"},{"q":"2","answer":"D","options":["happy","ready","slim","injured"],"explanation":"队员 injured 受伤离场。"},{"q":"3","answer":"A","options":["heart","weight","time","money"],"explanation":"lose heart 泄气。"},{"q":"4","answer":"B","options":["meals","times","rooms","songs"],"explanation":"difficult times 艰难时刻。"},{"q":"5","answer":"C","options":["weight","error","strength","noise"],"explanation":"mental strength 心理素质。"},{"q":"6","answer":"D","options":["ticket","medal","view","failure"],"explanation":"learn from every failure 从失败中学习。"},{"q":"7","answer":"A","options":["best","worst","least","most"],"explanation":"Do your best 尽力而为。"},{"q":"8","answer":"B","options":["late","fair","alone","fast"],"explanation":"play fair 公平竞赛。"},{"q":"9","answer":"C","options":["fear","stress","courage","trouble"],"explanation":"gave us courage 给我们勇气。"},{"q":"10","answer":"D","options":["cheat","rest","sleep","compete"],"explanation":"compete for the title 为冠军而战。"}]'::jsonb, 6);
