INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit) VALUES (10, 'Write a Page in a Wellness Book(为班级健康手册写一页)', 'A Travel Email', '假设你叫李华,你们班有一本''健康手册'',同学们在里面分享健康与健身的心得。请用英语写一页(约80词),描述你在运动或饮食上的一个积极改变,内容包括:① 你过去的问题或习惯;② 你做了什么改变;③ 改变带来的结果;④ 给同学的一条建议。注意用表示对比的词(instead of, rather than, now…)。', 'Suppose you are Li Hua. Your class keeps a wellness book where students share ideas about health and fitness. Write a page (about 80 words) describing one positive change you have made in exercise or eating, including: 1) your problem or habit in the past; 2) what change you made; 3) the result of the change; 4) one piece of advice for your classmates. Use words that show contrast (instead of, rather than, now…).', '["过去的问题/习惯(I used to … / In the past, I worried about …)","做出的改变(Instead of …, I … / Rather than …, I started …)","结果(Now I feel … / I have become both happier and healthier)","给同学的建议(My advice is … / Why not …?)"]'::jsonb, 70, 100, 'In the past, I worried about my weight all the time and tried every new diet I read about online. Then I decided to think about fitness rather than weight. Instead of cutting out the foods I enjoyed, I added healthy foods to my meals, and I started jogging for half an hour every morning. Now I feel both happier and healthier, and I have much more energy at school. My advice is simple: choose a sport you enjoy and train a little every day. Stay positive, and your body will thank you!', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["I decided to think about fitness rather than weight.","Instead of cutting out the foods I enjoyed, I added healthy foods to my meals.","Now I feel both happier and healthier, and I have much more energy.","Choose a sport you enjoy and train a little every day."]'::jsonb, '[{"wrong":"In the past I am worried about my weight.","correct":"In the past I worried about my weight.","note":"叙述过去的状态用一般过去时 worried。"},{"wrong":"Instead of cut out the foods, I added healthy foods.","correct":"Instead of cutting out the foods, I added healthy foods.","note":"instead of 后接动名词 cutting。"},{"wrong":"Now I become both happier and healthier.","correct":"Now I have become both happier and healthier.","note":"表示从过去到现在的变化用现在完成时 have become。"}]'::jsonb, '【健康手册一页结构】
